problems.solution_code:
#include <iostream>
using namespace std;

void swapWrong(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

void swap2(int &a, int &b) {
    int t = a;
    a = b;
    b = t;
}

int main() {
    int a, b;
    cin >> a >> b;

    swapWrong(a, b);
    cout << "值传递: " << a << " " << b << endl;

    swap2(a, b);
    cout << "引用传递: " << a << " " << b << endl;
    return 0;
}

