#include <iostream>
#include <iomanip>
using namespace std;

int sumOf(int a[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }
    return sum;
}

double averageOf(int a[], int n) {
    return 1.0 * sumOf(a, n) / n;
}

int main() {
    int n;
    cin >> n;
    int a[105];
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    cout << sumOf(a, n) << endl;
    cout << fixed << setprecision(2);
    cout << averageOf(a, n) << endl;
    return 0;
}

